PREFIX con: <http://ontorag.local/contract#>
PREFIX car: <http://ontorag.local/carbon#>
PREFIX top: <http://ontorag.local/top#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?amount ?paid ?applied ?remaining WHERE {
  ?contract top:identifier "C-2024-001" ;
            con:contractAmount ?amount ;
            con:paidAmount ?paid .
  ?payment a con:PaymentApplication ;
           con:appliesToContract ?contract ;
           top:identifier "PAY-1001" ;
           con:paymentAmount ?applied .
  BIND((?amount * (1 - 0.05)) - ?paid AS ?remaining)
}

